abhinav_20_23 = {
    'hi': '।।6.20--6.23।। श्री अभिनवगुप्त कहते हैं: योग के अभ्यास से निरुद्ध हुआ चित्त जिस अवस्था में उपराम (शान्त) हो जाता है, और जिस अवस्था में आत्मा द्वारा आत्मा को देखता हुआ अपने आप में ही सन्तुष्ट रहता है; जिस अवस्था में अतीन्द्रिय, केवल बुद्धि-ग्राह्य अत्यन्तिक सुख का अनुभव करता है और जिसमें स्थित होकर तत्त्व से विचलित नहीं होता; तथा जिसे पाकर उससे अधिक कोई लाभ नहीं मानता और जिसके प्राप्त होने पर भारी दुःख से भी विचलित नहीं होता; दुःखों के संयोग के वियोग रूप उस अवस्था को \"योग\" संज्ञा दी गई है। उस योग को बिना उद्वेग के (निश्चयपूर्वक) निष्काम चित्त से सिद्ध करना चाहिए।',
    'en': '6.20--6.23 Sri Abhinavagupta states: When the mind, restrained by the practice of Yoga, attains absolute quietude, and when beholding the Self by the self, one rests satisfied within the Self alone; when one experiences that boundless joy which transcends the senses and is grasped solely by purified intellect, and established in which one never swerves from the Truth; obtaining which one regards no other gain as superior, and anchored in which one is not shaken even by heavy sorrow—know that severance from union with pain to be called Yoga. That Yoga should be practiced with unshakeable resolve and an undaunted heart.',
    'be': '৬.২০--৬.২৩ শ্রী অভিনবগুপ্ত বলেছেন: যোগের অভ্যাস থেকে নিরুদ্ধ হওয়া চিত্ত যে অবস্থায় উপরম (শান্ত) হয়ে যায়, এবং যে অবস্থায় আত্মা দ্বারা আত্মাকে দেখতে দেখতে নিজের আপনাতেই সন্তুষ্ট থাকে; যে অবস্থায় অতীতিন্দ্রিয়, কেবল বুদ্ধি-গ্রাহ্য অত্যন্তিক সুখের অভিজ্ঞতা করে এবং যাতে স্থিত হয়ে তত্ত্ব থেকে বিচলিত হয় না; তথা যাকে পেয়ে তার থেকে অধিক কোন লাভ মানে না এবং যার প্রাপ্তি হলে ভারী দুঃখ থেকেও বিচলিত হয় না; দুঃখের সং যোগের বিয়োগ রূপ সেই অবস্থাকে "যোগ" সংজ্ঞা দেওয়া হয়েছে। সেই যোগকে বিনা উদ্বেগের (নিশ্চয়পূর্ব ক) নিষ্কাম চিত্ত থেকে সিদ্ধ করা উচিত।',
    'ka': '೬.೨೦--೬.೨೩ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಯೋಗಾಭ್ಯಾಸದಿಂದ ನಿರುದ್ಧವಾದ ಚಿತ್ತವು ಯಾವ ಅವಸ್ಥೆಯಲ್ಲಿ ಉಪರಮವನ್ನು (ಶಾಂತಿ) ಪಡೆಯುತ್ತದೆಯೋ, ಹಾಗೂ ಯಾವ ಅವಸ್ಥೆಯಲ್ಲಿ ಆತ್ಮನಿಂದ ಆತ್ಮನನ್ನು ನೋಡುತ್ತಾ ತನ್ನಲ್ಲೇ ಸಂತುಷ್ಟನಾಗಿರುತ್ತಾನೋ; ಯಾವ ಅವಸ್ಥೆಯಲ್ಲಿ ಅತೀಂದ್ರಿಯವೂ ಕೇವಲ ಬುದ್ಧಿಗ್ರಾಹ್ಯವೂ ಆದ ಆತ್ಯಂತಿಕಸುಖವನ್ನು ಅನುಭವಿಸುತ್ತಾನೋ ಹಾಗೂ ಯಾವುದರಲ್ಲಿ ಸ್ಥಿತನಾಗಿ ತತ್ತ್ವದಿಂದ ವಿಚಲಿತನಾಗುವುದಿಲ್ಲವೋ; ಹಾಗೂ ಯಾವುದನ್ನು ಪಡೆದು ಅದಕ್ಕಿಂತಲೂ ಹೆಚ್ಚಿನ ಲಾಭವನ್ನು ಭಾವಿಸುವುದಿಲ್ಲವೋ ಮತ್ತು ಯಾವುದರ ಪ್ರಾಪ್ತಿಯಾದಾಗ ಭಾರೀ ದುಃಖದಿಂದಲೂ ವಿಚಲಿತನಾಗುವುದಿಲ್ಲವೋ; ದುಃಖಗಳ ಸಂಯೋಗದ ವಿಯೋಗರೂಪದ ಆ ಅವಸ್ಥೆಗೆ "ಯೋಗ" ಎಂಬ ಸಂಜ್ಞೆಯನ್ನು ನೀಡಲಾಗಿದೆ. ಆ ಯೋಗವನ್ನು ಉದ್ವೇಗವಿಲ್ಲದೆ (ನಿಶ್ಚಯಪೂರ್ವಕ) ನಿಷ್ಕಾಮಚಿತ್ತದಿಂದ ಸಿದ್ಧಿಸಿಕೊಳ್ಳಬೇಕು'
}

abhinav_24_25 = {
    'hi': '।।6.24--6.25।। श्री अभिनवगुप्त कहते हैं: संकल्प से उत्पन्न होने वाली समस्त कामनाओं को पूर्ण रूप से त्यागकर और मन के द्वारा इन्द्रियों के समूह को सब ओर से वश में करके; धैर्ययुक्त बुद्धि के द्वारा धीरे-धीरे उपराम (शान्त) होवे, और मन को आत्मा में अचल स्थापित करके फिर किसी भी वस्तु का चिन्तन न करे।',
    'en': '6.24--6.25 Sri Abhinavagupta states: Completely renouncing all desires born of mental resolves without reserve, and thoroughly restraining the entire group of senses from all sides by the mind; let him attain quietude little by little with intellect held in steadfast fortitude, and making the mind firmly established in the Self, let him not think of anything whatsoever.',
    'be': '৬.২৪--৬.২৫ শ্রী অভিনবগুপ্ত বলেছেন: সং কল্প থেকে উৎপন্ন হওয়া সমস্ত কামনাকে পূর্ণ রূপে ত্যাগ করে এবং মনের দ্বারা ইন্দ্রিয়ের সমূহকে সব দিক থেকে বশে করে; ধৈর্যযুক্ত বুদ্ধির দ্বারা ধীরে-ধীরে উপরম (শান্ত) হোক, এবং মনকে আত্মায় অচল স্থাপিত করে আবার কোন বস্তুর চিন্তন না করুক।',
    'ka': '೬.೨೪--೬.೨೫ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಸಂಕಲ್ಪದಿಂದ ಉಂಟಾಗುವ ಸಮಸ್ತ ಕಾಮನೆಗಳನ್ನೂ ಪೂರ್ಣವಾಗಿ ತ್ಯಜಿಸಿ ಹಾಗೂ ಮನಸ್ಸಿನ ಮೂಲಕ ಇಂದ್ರಿಯಗಳ ಸಮೂಹವನ್ನು ಎಲ್ಲ ಕಡೆಯಿಂದಲೂ ವಶಪಡಿಸಿಕೊಂಡು; ಧೈರ್ಯಯುಕ್ತವಾದ ಬುದ್ಧಿಯಿಂದ ಕ್ರಮೇಣವಾಗಿ ಉಪರಮನಾಗಲಿ (ಶಾಂತ), ಹಾಗೂ ಮನಸ್ಸನ್ನು ಆತ್ಮನಲ್ಲಿ ಅಚಲವಾಗಿ ಸ್ಥಾಪಿಸಿ ನಂತರ ಇನ್ಯಾವ ವಸ್ತುವಿನ ಚಿಂತನೆಯನ್ನೂ ಮಾಡದಿರಲಿ'
}

